use std::{collections::BTreeMap,fs};fn main(){let mut rows=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/cyclotomic-cost/CONTROL.tsv").unwrap().lines().skip(1){let v:Vec<String>=l.split('\t').map(str::to_string).collect();assert_eq!(v.len(),10);let n=|j:usize|v[j].parse::<u64>().unwrap();let k=(n(0),n(1),n(2),n(3),n(4));let c:Vec<u64>=v[9].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(c.len(),16);assert_eq!(c[8],2*c[7]+c[5]+c[6]);if k.2==1{let old:&Vec<String>=&rows[&(k.0,k.1,0,k.3,k.4)];assert_eq!(&old[5..],&v[5..]);}assert!(rows.insert(k,v).is_none());}assert_eq!(rows.len(),48);println!("p\tsm\tmodulus\teager_REDC\tring_REDC\teager_over_ring_REDC\teager_rows\tring_rows\teager_anchor\tring_anchor");let mut range=BTreeMap::<bool,(f64,f64)>::new();for(&(p,sm,rep,arm,modulus),v)in &rows{if rep!=0||arm!=0{continue}let b=&rows[&(p,sm,0,1,modulus)];assert_eq!(&v[5..7],&b[5..7]);let a:Vec<u64>=v[9].split(',').map(|x|x.parse().unwrap()).collect();let bb:Vec<u64>=b[9].split(',').map(|x|x.parse().unwrap()).collect();let ratio=a[8]as f64/bb[8]as f64;let e=range.entry(p==modulus).or_insert((ratio,ratio));e.0=e.0.min(ratio);e.1=e.1.max(ratio);println!("{p}\t{sm}\t{modulus}\t{}\t{}\t{ratio:.6}\t{}\t{}\t{}\t{}",a[8],bb[8],v[7],b[7],v[8],b[8]);}for(base,(lo,hi))in range{eprintln!("base_field={base} min_eager_over_ring_REDC={lo:.6} max_eager_over_ring_REDC={hi:.6}");}eprintln!("records=48 all_repeats_same_action_target_REDC_identity=true producer_costs_excluded=true");}
